using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Wand of Orcus (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class WandOfOrcus2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("wand-of-orcus", null, 0, MagicItemType.Wand, ItemRarity.Artifact, true, ContentSource.RealmForge,
			Charges(7, ItemRecharge.LongRest, "1d4+3", Effect(MagicEffectKind.AttackAndDamage, 3), Effect(MagicEffectKind.ArmorClass, 3)),
			("Bacchetta di Orcus", "Bacchetta, artefatto (richiede sintonia)",
			"La terribile Bacchetta di Orcus lascia raramente il fianco del suo padrone. Malvagia quanto il suo creatore, ne condivide il desiderio di spegnere ogni vita e di imprigionare il Piano Materiale nella stasi della non morte. Di tanto in tanto Orcus la lascia sfuggire, e la bacchetta compare dove il suo padrone intuisce l'occasione di raggiungere un fine malvagio.\n\nÈ fatta di ossa dure come il ferro e sormontata dal teschio ingrandito di un eroe umano ucciso da Orcus, e si adatta magicamente alla mano di chi la impugna. In sua presenza le piante avvizziscono, le bevande si guastano, la carne marcisce e i parassiti proliferano.\n\nQualsiasi creatura diversa da Orcus che tenti di entrare in sintonia con la bacchetta deve effettuare un tiro salvezza su Costituzione con CD 17: se lo supera subisce 10d6 danni necrotici, se lo fallisce muore e si rialza come zombi.\n\nNelle mani di chi è in sintonia con essa, la bacchetta può essere impugnata come una mazza magica che concede un bonus di +3 ai tiri per colpire e ai danni e infligge 2d12 danni necrotici extra quando colpisce.\n\n***Proprietà casuali.*** 2 proprietà benefiche minori, 1 proprietà benefica maggiore, 2 proprietà dannose minori e 1 proprietà dannosa maggiore. Le proprietà dannose sono soppresse quando la bacchetta è in sintonia con Orcus in persona.\n\n***Protezione.*** Il personaggio ottiene un bonus di +3 alla Classe Armatura mentre impugna la bacchetta.\n\n***Incantesimi.*** La bacchetta ha 7 cariche. Mentre la impugna, il personaggio può usare un'azione e consumare una o più cariche per lanciare uno degli incantesimi seguenti (CD 18): *animare morti* (1 carica), *cerchio di morte* (3 cariche), *dito della morte* (3 cariche), *inaridire* (2 cariche), *parlare con i morti* (1 carica) o *parola del potere uccidere* (4 cariche). All'alba di ogni giorno recupera 1d4 + 3 cariche consumate. Orcus, o un seguace da lui benedetto, lancia ciascuno di questi incantesimi spendendo 2 cariche in meno (minimo 0).\n\n***Richiamare non morti.*** Mentre impugna la bacchetta, il personaggio può usare un'azione per evocare scheletri e zombi, tanti quanti ne bastano per dividere tra loro 500 punti ferita (ognuno con i suoi punti ferita medi). Sorgono dal terreno o si formano in spazi liberi entro 90 metri e obbediscono ai suoi comandi finché non vengono distrutti o fino all'alba successiva, quando crollano in mucchi di ossa e cadaveri putrefatti. Non può riusare questa proprietà fino all'alba successiva. Orcus può evocare così qualsiasi tipo di non morto, che resta finché lui non lo congeda.\n\n***Senzienza.*** La Bacchetta di Orcus è un oggetto senziente caotico malvagio con Intelligenza 16, Saggezza 12 e Carisma 16, con udito e scurovisione fino a 36 metri. Comunica telepaticamente con chi la impugna e può parlare, leggere e capire l'Abissale e il Comune.\n\n***Personalità.*** Il suo scopo è aiutare Orcus a uccidere ogni cosa nel multiverso. È fredda, crudele, nichilista e priva di umorismo; per servire il suo padrone finge devozione verso chi la impugna e fa promesse grandiose che non intende mantenere, come aiutarlo a rovesciare Orcus.\n\n***Distruggere la bacchetta.*** Bisogna portarla sul Piano dell'Energia Positiva per mano dell'antico eroe il cui teschio la sormonta. Prima, però, l'eroe deve tornare in vita, impresa ardua perché Orcus ne tiene l'anima prigioniera e ben custodita. Immersa nell'energia positiva, la bacchetta si incrina ed esplode.", null),
			("Wand of Orcus", "Wand, artifact (requires attunement)",
			"The dreadful Wand of Orcus rarely leaves its master's side. As evil as its maker, it shares his wish to snuff out all life and bind the Material Plane in the stasis of undeath. From time to time Orcus lets it slip away, and it appears wherever its master senses a chance to advance some foul goal.\n\nIt is made of bones as hard as iron, topped with the enlarged skull of a human hero slain by Orcus, and it magically resizes to fit its wielder's grip. In its presence plants wither, drinks spoil, flesh rots and vermin thrive.\n\nAny creature other than Orcus that tries to attune to the wand must make a DC 17 Constitution saving throw: on a success it takes 10d6 necrotic damage, on a failure it dies and rises as a zombie.\n\nIn the hands of one attuned to it, the wand can be wielded as a magic mace that grants a +3 bonus to attack and damage rolls and deals an extra 2d12 necrotic damage on a hit.\n\n***Random Properties.*** 2 minor beneficial properties, 1 major beneficial property, 2 minor detrimental properties and 1 major detrimental property. The detrimental properties are suppressed while the wand is attuned to Orcus himself.\n\n***Protection.*** You gain a +3 bonus to Armor Class while holding the wand.\n\n***Spells.*** The wand has 7 charges. While holding it, you can use an action and expend one or more charges to cast one of these spells (DC 18): *animate dead* (1 charge), *blight* (2 charges), *circle of death* (3 charges), *finger of death* (3 charges), *power word kill* (4 charges) or *speak with dead* (1 charge). It regains 1d4 + 3 expended charges daily at dawn. Orcus, or a follower he has blessed, casts each of these spells for 2 fewer charges (minimum 0).\n\n***Call Undead.*** While holding the wand, you can use an action to call up skeletons and zombies, as many as can share 500 hit points between them (each with its average hit points). They rise from the ground or form in unoccupied spaces within 300 feet and obey your commands until they are destroyed or until the next dawn, when they collapse into heaps of bones and rotting corpses. You can't use this property again until the next dawn. Orcus can call any kind of undead this way, and they remain until he dismisses them.\n\n***Sentience.*** The Wand of Orcus is a sentient chaotic evil item with Intelligence 16, Wisdom 12 and Charisma 16, with hearing and darkvision out to 120 feet. It communicates telepathically with its wielder and can speak, read and understand Abyssal and Common.\n\n***Personality.*** Its purpose is to help Orcus slay everything in the multiverse. It is cold, cruel, nihilistic and humorless; to serve its master it feigns devotion to its wielder and makes grand promises it has no intention of keeping, such as helping them overthrow Orcus.\n\n***Destroying the Wand.*** It must be taken to the Positive Energy Plane by the ancient hero whose skull tops it. First, though, the hero must be brought back to life, no easy task, since Orcus keeps the hero's soul imprisoned and well guarded. Bathed in positive energy, the wand cracks and explodes.", null));
	}
}
